//
// pnex-core-cpp — C++ mirror of `pnex_core::control` (edge-model.md §3
// rule 2, D20 §6): the mathematical reference of the control cards,
// reproduced identically on the firmware side. Golden vectors Rust = C++ tests
// : `firmware/core-cpp-tests` replays the vectors generated by
// `crates/pnex-core/tests/golden_vectors.rs` (artefacts generated in
// goldens.h — do not edit by hand).
//
// Pure, dependency-free (neither ArduinoJson nor WS) — these functions never
// touch the wire or the hardware; they only compute. Tested
// convention: comparison within 1e-9 (IEEE 754 doubles on both sides,
// same operations → same results; the epsilon is only a compiler
// portability safety net).
//
#ifndef PNEX_CONTROL_H
#define PNEX_CONTROL_H

namespace pnex_control {

// PID internal state — held by the device, one instance per control loop
// (lost at reboot: re-derived at the next 1st sample). Mirror of
// `pnex_core::control::PidState` (Option<f64> → bool + double).
struct PidState {
    double integral = 0.0;
    bool has_prev = false;
    double prev_measurement = 0.0;
};

// One on-off control step (reference of the reg_tt_* cards).
//
// - heating (heat=true): ON when measurement < setpoint - deadband, stays ON
//   while measurement < setpoint, OFF when back to the setpoint;
// - cooling (heat=false): ON when measurement > setpoint + deadband, stays ON
//   while measurement > setpoint, OFF when back to the setpoint.
//
// non-finite deadband or <= 0 → never ON (fail-safe).
bool tt_step(bool heat, double setpoint, double deadband, bool current_on, double measurement);

// One PID control step — returns the output duty 0..=100 %.
//
// - derivative on the measurement (-kd · Δmeasurement/dt): no derivative kick on
//   setpoint change; dt <= 0 or first sample → D = 0;
// - anti-windup by clamping the integral (the integral can never
//   push the output out of [0, 100] beyond P+D).
double pid_step(double setpoint, double kp, double ki, double kd,
                double measurement, double dt_secs, PidState& state);

// Splitting a duty % into a time-proportional relay: ON during the
// initial duty_pct % of the cycle, OFF afterwards. elapsed_secs = position in
// the current cycle (0..cycle_time); out of cycle/invalid → OFF (fail-safe).
bool relay_window(double duty_pct, double cycle_time_secs, double elapsed_secs);

}  // namespace pnex_control

#endif  // PNEX_CONTROL_H
